def separate_paren_groups(paren_string: str) -> List[str]:
    # Step 1: Remove spaces from the input string
    paren_string = paren_string.replace(" ", "")

    # Step 2: Identify and extract each group of nested parentheses
    groups = []
    current_group = ""
    open_count = 0

    for char in paren_string:
        if char == "(":
            open_count += 1
        elif char == ")":
            open_count -= 1

        current_group += char

        if open_count == 0:
            groups.append(current_group)
            current_group = ""

    # Step 3, 4, 5: Separate each group into balanced strings that are not nested within each other
    result = []

    for group in groups:
        stack = []
        balanced_group = ""

        for char in group:
            if char == "(":
                stack.append(char)
                balanced_group += char
            elif char == ")":
                if stack:
                    stack.pop()
                    balanced_group += char
                else:
                    break

        if not stack:
            result.append(balanced_group)

    return result

